// Verus program for constructing a single-row grid of length n,
// where the row elements are exactly their indices (u8), strictly increasing.
//
// Requirements:
// - n is a u8 (0 <= n <= 255)
// - The returned grid has exactly one row
// - The row length is exactly n
// - For each index i in [0..n), row[i] = i as u8
// - If n = 0, the row is empty
//
// This program provides two functions:
// 1. create_row(n): returns the single vector of u8 containing [0, 1, ..., n-1]
// 2. indices(n): returns a Vec<Vec<u8>> with exactly one row being create_row(n)

verus! {

fn create_row(n: u8) -> (row: Vec<u8>)
  ensures row.len() == n as usize
  ensures forall|i: usize| i < row.len() ==> row[i] as u8 == i as u8
  ensures forall|i: usize, j: usize| 0 <= i && i < j && j < row.len() ==> row[i] < row[j]
{
    let mut row = Vec::new();
    let mut i: usize = 0;
    // we must have a decreasing measure to prove termination for loop
    // decreasing from n to 0 represented as n - i
    while i < n as usize
        invariant i <= n as usize
        invariant row.len() == i
        invariant forall|k: usize| k < i ==> row[k] as u8 == k as u8
        decreases n as usize - i
    {
        row.push(i as u8);
        i = i + 1;
    }
    row
}

fn indices(n: u8) -> (grid: Vec<Vec<u8>>)
  ensures grid.len() == 1
  ensures grid[0].len() == n as usize
  ensures forall|i: usize| i < grid[0].len() ==> grid[0][i] == (i as u8)
  ensures forall|i: usize, j: usize| 0 <= i && i < j && j < grid[0].len() ==> grid[0][i] < grid[0][j]
{
    let row = create_row(n);
    let mut grid = Vec::new();
    grid.push(row);
    grid
}

}